using System;
using System.IO;
using System.Runtime.Serialization.Json;
using System.Text;
using System.Xml;
using CircuitoStudio;
internal static class EnclosureTests {
 static int count;static void Check(bool value,string name){count++;if(!value)throw new Exception(name);}
 [STAThread] public static int Main(){try{
  Board b=new Board();Check(b.Enclosure.Rows==4&&b.Enclosure.ModulesPerRow==24,"defaults");b.Enclosure=null;Check(b.Enclosure.WidthMm==600,"lazy null");
  using(MemoryStream ms=new MemoryStream(Encoding.UTF8.GetBytes("{\"Id\":\"Q\",\"Name\":\"Old\",\"Voltage\":220,\"Circuits\":[]}"))){Board old=(Board)new DataContractJsonSerializer(typeof(Board)).ReadObject(ms);Check(old.Enclosure.Rows==4,"old schema lazy constructor bypass");}
  b.Enclosure.Rows=1;b.Enclosure.ModulesPerRow=4;b.Circuits.Add(new Circuit{Id="A"});b.Circuits.Add(new Circuit{Id="B"});Check(Enclosures.Validate(b).Count==0,"exact capacity");Check(Enclosures.Layout(b)[1].Column==3,"first fit");b.Circuits.Add(new Circuit{Id="C"});Check(Enclosures.Validate(b).Exists(x=>x.Contains("capacidade total")),"capacity overflow");Check(!Enclosures.Layout(b)[2].Placed,"unplaced overflow");
  b.Circuits.RemoveAt(2);b.Circuits[1].DinRow=1;b.Circuits[1].DinColumn=1;Check(Enclosures.Layout(b)[0].Column==3,"manual reserved before auto");b.Circuits[0].DinRow=1;b.Circuits[0].DinColumn=2;Check(Enclosures.Validate(b).Exists(x=>x.Contains("sobreposição")),"manual overlap");
  b.Circuits[0].DinColumn=4;Check(Enclosures.Validate(b).Exists(x=>x.Contains("posição inválida")),"manual bounds");b.Circuits[0].DinRow=0;b.Circuits[0].DinColumn=1;Check(!Enclosures.Layout(b)[0].Placed,"half manual invalid");
  b.Circuits[0].DinColumn=0;b.Circuits[0].DinModules=5;Check(!Enclosures.Layout(b)[0].Placed,"oversized module");b.Circuits[0].DinModules=-2;Check(Enclosures.Validate(b).Exists(x=>x.Contains("negativos")),"negative modules warn");
  b.Enclosure.ModulePitchMm=Double.NaN;Check(Enclosures.Validate(b).Count==1,"invalid pitch safe");b.Enclosure.ModulePitchMm=18;b.Enclosure.WidthMm=50;Check(Enclosures.Validate(b).Exists(x=>x.Contains("largura")),"physical width");b.Enclosure.WidthMm=600;
  b.Enclosure.Rows=4;b.Enclosure.HeightMm=100;Check(Enclosures.Validate(b).Exists(x=>x.Contains("altura")),"physical height");b.Enclosure.HeightMm=800;b.Name="Q & <test>";b.Circuits[0].Id="C&<1>";
  XmlDocument doc=new XmlDocument();doc.XmlResolver=null;doc.LoadXml(Enclosures.Svg(new Project{Name="P & A"},b,"T < >"));Check(doc.DocumentElement.LocalName=="svg","svg valid xml escaping");Check(doc.InnerText.Contains("Q & <test>"),"svg content");
  using(MemoryStream ms=new MemoryStream()){DataContractJsonSerializer serializer=new DataContractJsonSerializer(typeof(Board));serializer.WriteObject(ms,b);ms.Position=0;Board q=(Board)serializer.ReadObject(ms);Check(q.Enclosure.Rows==4&&q.Circuits[1].DinColumn==1,"roundtrip layout");}
  var project=Project.CreateSample();var board=project.Boards[0];int changes=0;using(var form=new EnclosureForm(project,board,delegate{changes++;})){form.CreateControl();Check(!form.Changed&&changes==0,"opening enclosure does not alter project");foreach(int rows in new[]{1,2,3,4})foreach(int modules in new[]{12,24}){var spec=Enclosures.Generic(rows,modules);form.ApplySpec(spec);Check(board.Enclosure.Rows==rows&&board.Enclosure.ModulesPerRow==modules&&Enclosures.Validate(board).Count==0,"generic geometry fits footprint");spec.WidthMm=1;Check(board.Enclosure.WidthMm>1,"selected enclosure copied independently");}Check(form.Changed&&changes==8,"selection immediately notifies autosave");
   var before=board.Enclosure;bool failed=false;try{form.ApplySpec(new EnclosureSpec{WidthMm=Double.NaN});}catch(InvalidDataException){failed=true;}Check(failed&&Object.ReferenceEquals(before,board.Enclosure)&&changes==8,"invalid selection preserves previous enclosure");board.Circuits[0].DinRow=board.Circuits[1].DinRow=1;board.Circuits[0].DinColumn=board.Circuits[1].DinColumn=1;Check(Enclosures.Validate(board).Exists(x=>x.Contains("sobreposição")),"manual collision reported before rearrangement");form.AutoArrange();Check(changes==9&&Enclosures.Validate(board).Count==0&&Enclosures.Layout(board)[1].Column==3,"automatic distribution clears collisions and notifies");form.AutoArrange();Check(changes==9,"no change event for unchanged automatic layout");}
  string directory=Path.Combine(Path.GetTempPath(),"enclosure-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(directory);try{board.Enclosure.Manufacturer="Fabricante informado Ω";board.Enclosure.Reference="Referência ç";board.Circuits[1].DinRow=2;board.Circuits[1].DinColumn=4;string path=Path.Combine(directory,"layout.circuito");project.Save(path);var loaded=Project.Load(path);Check(loaded.Boards[0].Enclosure.Manufacturer==board.Enclosure.Manufacturer&&loaded.Boards[0].Enclosure.Reference==board.Enclosure.Reference,"manufacturer and reference persist");Check(loaded.Boards[0].Circuits[1].DinRow==2&&Enclosures.Layout(loaded.Boards[0])[1].Column==4,"manual position survives project reopen");Check(Enclosures.Svg(project,board,"Teste")==Enclosures.Svg(loaded,loaded.Boards[0],"Teste"),"SVG matches saved geometry");}finally{Directory.Delete(directory,true);}
  Console.WriteLine("Enclosure checks passed: "+count);return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
